@@ -0,0 +1,39 @@
+// Sites (kitchens). Every location belongs to one site; batches, stock-takes
+// and temperature readings belong to the site of their location. Items,
+// suppliers, recipes and dishes are shared by all sites. Domain functions
+// take an optional `site`; without one they see every site (tools, jobs).
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none, and of every location before schema 3. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in file order. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** A test for records with a `location`: true when it is in `site` (always true without a site). */
+export function inSite(store, site) {
+  if (site === undefined) return () => true;
+  const siteOf = new Map(store.data.locations.map((l) => [l.id, l.site]));
+  return (record) => (siteOf.get(record.location) ?? DEFAULT_SITE) === site;
+}
+
+/** The locations of `site` (every location without a site). */
+export function listLocations(store, site) {
+  return store.data.locations.filter((l) => site === undefined || l.site === site);
+}
+
+/** One location of `site`, or AppError unknown_location. */
+export function getLocation(store, id, site) {
+  const location = listLocations(store, site).find((l) => l.id === id);
+  if (!location) throw new AppError("unknown_location", { id });
+  return location;
+}
